    this.hud.audio = this.audio;

    // 横屏包装层：小工具容器/WebView 常被宿主 App 锁定为竖屏、无法跟随设备旋转
    //（skill 文档明确 requestFullscreen / orientation.lock / PointerLock 均不可用），
    // 把全部游戏 DOM 包进一层，视口为竖屏时整体 CSS 旋转 90° 强制横屏
    const gameRoot = document.createElement('div');
    gameRoot.id = 'gameRoot';
    for (const el of Array.from(document.body.children)) {
      if (el.tagName !== 'SCRIPT') gameRoot.appendChild(el);
    }
    document.body.appendChild(gameRoot);
    this.gameRoot = gameRoot;
    this._rotated = false;

    // Three 基础设施
    this.renderer = new THREE.WebGLRenderer({ antialias: true, powerPreference: 'high-performance' });
    this.renderer.setSize(window.innerWidth, window.innerHeight);
    // 像素比上限：触屏设备 1.5（高 DPR 手机像素压力最大，降级显著提帧率），桌面 2
    const isTouch = ('ontouchstart' in window) || navigator.maxTouchPoints > 0;
    // 低端设备降级（#3）：核数 ≤4 → 关软阴影/降 DPR，缓解低端机掉帧
    const lowEnd = (navigator.hardwareConcurrency || 8) <= 4;
    this.renderer.setPixelRatio(Math.min(window.devicePixelRatio, lowEnd ? 1.25 : (isTouch ? 1.5 : 2)));
    this.renderer.shadowMap.enabled = !lowEnd;
    this.renderer.shadowMap.type = lowEnd ? THREE.PCFShadowMap : THREE.PCFSoftShadowMap;
    this.renderer.shadowMap.mapSize.set(1024, 1024);
    this.renderer.outputColorSpace = THREE.SRGBColorSpace;
    // toneMapping（#1）：ACESFilmic 收敛高光，避免环境光强 >1 时过曝
    this.renderer.toneMapping = THREE.ACESFilmicToneMapping;
    this.renderer.toneMappingExposure = 1.1;
    gameRoot.appendChild(this.renderer.domElement);

    this.scene = new THREE.Scene();
    this.camera = new THREE.PerspectiveCamera(CONFIG.fov, window.innerWidth / window.innerHeight, 0.05, CONFIG.renderDistance);
    this.scene.add(this.camera);

    // 环境贴图：程序化室内光照（PMREM），让金属枪械/装甲有真实反射，否则金属像灰塑料
    this.scene.environment = this._buildEnvironment();

    // 地图
    this.gameMap = new GameMap(this.scene);

    // 玩家
    this.player = new Player(this.camera, this.gameMap, this.hud);

    // 敌人数组（动态引用，weapon 通过此数组找目标）
    this.enemies = [];

    // 武器系统（依赖 enemies 引用）
    this.weapons = new WeaponSystem(this.scene, this.camera, this.player, this.gameMap, this.enemies, this.hud, this.audio);

    // 补给拾取系统（血包 + 弹药包，弹药包需要 weapons 引用补弹）
    this.pickups = new PickupSystem(this.scene, this.gameMap, this.player, this.hud, this.audio, this.weapons);

    // 小地图数据源（必须在 gameMap/player/enemies 都创建完后）
    this.hud.setMinimapRefs(
      this.gameMap,
      this.player,
      () => this.enemies,
      () => this.pickups ? this.pickups.pickups : []
    );

    // 贴图懒加载（#2）：textures.js（5.2MB base64）不阻塞启动，菜单期后台注入解析，
    // 完成后把真实贴图应用到已建的地图/武器材质（此前用程序化兜底先行渲染）
    const texScript = document.createElement('script');
    texScript.src = 'textures.js';
    texScript.onload = () => {
      if (this.gameMap && this.gameMap.applyTextures) this.gameMap.applyTextures();
      if (this.weapons && this.weapons.applyTextures) this.weapons.applyTextures();
    };
    document.head.appendChild(texScript);

